fn str_at(xs: List[Str], i: Int) -> Str {
    match xs.get(i) {
        Some(v) => {
            return v
        }
        None => {
            return ""
        }
    }
}

fn valid_char(c: Str) -> Bool {
    return c == "." or (c >= "1" and c <= "9")
}

fn same_unit(a: Int, b: Int) -> Bool {
    let ar = a / 9
    let ac = a - ar * 9
    let br = b / 9
    let bc = b - br * 9
    if ar == br or ac == bc {
        return true
    }
    return ar / 3 == br / 3 and ac / 3 == bc / 3
}

pub fn sudoku(rows: List[Str]) -> Bool {
    if rows.len() != 9 {
        return false
    }
    var flat: List[Str] = []
    for row in rows {
        var n = 0
        for c in row.chars() {
            if not valid_char(c) {
                return false
            }
            flat = flat.push(c)
            n = n + 1
        }
        if n != 9 {
            return false
        }
    }

    var p = 0
    while p < 81 {
        let v = str_at(flat, p)
        if v != "." {
            var q = 0
            while q < 81 {
                if q != p and str_at(flat, q) == v and same_unit(a: p, b: q) {
                    return false
                }
                q = q + 1
            }
        }
        p = p + 1
    }
    return true
}
